def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq'}
    trades = []
    seq_counter = 0

    for order in orders:
        seq_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0:
            # discard stale/invalid entries at the top of the heap
            while heap:
                top = heap[0]
                if side == 'buy':
                    p, s, rid = top
                else:
                    negp, s, rid = top
                    p = -negp
                if rid not in book or book[rid]['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                break

            if not heap:
                break

            top = heap[0]
            if side == 'buy':
                p, s, rid = top
            else:
                negp, s, rid = top
                p = -negp

            if typ != 'market':
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            resting = book[rid]
            trade_qty = min(remaining, resting['qty'])
            trade_price = resting['price']

            if side == 'buy':
                trades.append([oid, rid, trade_price, trade_qty])
            else:
                trades.append([rid, oid, trade_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                heapq.heappop(heap)
                del book[rid]

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

